fn rotate(a: &[i32], offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }
    // Effective rotation offset mod n
    let k = offset % n;
    // If k == 0, the rotation is a no-op
    if k == 0 {
        return a.to_vec();
    }
    // Build the rotated vector by concatenating the two slices
    a[k..].iter().chain(a[..k].iter()).cloned().collect()
}

